css:
/* ============================================================
   Anki · Lexicon redesign — STYLING (shared by Front + Back)
   Clean dictionary look. Night mode → dark theme.
   ============================================================ */
@import url('https://fonts.googleapis.com/css2?family=Literata:ital,opsz,wght@0,7..72,400;0,7..72,600;0,7..72,700;1,7..72,400;1,7..72,600&family=Golos+Text:wght@400;500;600;700&family=JetBrains+Mono:wght@500;600&display=swap');

:root {
  --word-size: 96px;
  --accent: oklch(0.55 0.13 42);

  --bg:        oklch(0.962 0.013 84);
  --bg-2:      oklch(0.945 0.015 82);
  --surface:   oklch(0.988 0.007 84);
  --ink:       oklch(0.245 0.012 60);
  --ink-soft:  oklch(0.40 0.012 62);
  --muted:     oklch(0.56 0.012 66);
  --faint:     oklch(0.68 0.010 70);
  --line:      oklch(0.86 0.012 78);
  --line-soft: oklch(0.90 0.010 80);
  --hl:        oklch(0.55 0.13 42 / 0.16);
}

/* Anki night mode → dark palette */
.card.nightMode, .nightMode, .night_mode {
  --bg: oklch(0.205 0.008 70); --bg-2: oklch(0.235 0.009 70); --surface: oklch(0.255 0.009 70);
  --ink: oklch(0.93 0.010 80); --ink-soft: oklch(0.80 0.012 78); --muted: oklch(0.64 0.012 76);
  --faint: oklch(0.52 0.012 74); --line: oklch(0.36 0.012 74); --line-soft: oklch(0.31 0.010 72);
  --hl: oklch(0.70 0.12 50 / 0.22);
}

* { box-sizing: border-box; }

/* Anki container reset */
.card {
  background: var(--bg); color: var(--ink); text-align: left; padding: 0;
  font-family: "Golos Text", ui-sans-serif, system-ui, sans-serif;
  -webkit-font-smoothing: antialiased; text-rendering: optimizeLegibility;
}
html, body {
  margin: 0; padding: 0;
  background: var(--bg); color: var(--ink);
  font-family: "Golos Text", ui-sans-serif, system-ui, sans-serif;
}
#answer { border: 0; margin: 0; }

/* ---- sheet (one card side) ---- */
.sheet {
  max-width: 1180px;
  margin: 0 auto;
  padding: clamp(32px, 5vw, 80px) clamp(20px, 5vw, 80px) 96px;
}
.sheet[hidden] { display: none; }
[data-density="compact"] .sheet { padding-top: clamp(28px, 4vw, 60px); }

/* ---- tiny mono service label ---- */
.k {
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 11.5px; font-weight: 600; letter-spacing: 0.18em;
  text-transform: uppercase; color: var(--faint);
}

/* ============================================================
   HERO — the word is the star (shared by Front + Back)
   ============================================================ */
.hero { padding-bottom: clamp(24px, 3.4vw, 40px); }
.hero .k.eyebrow { display: block; margin-bottom: 16px; }
.hero .k.eyebrow .pos { color: var(--accent); }

.word, h1.word, h2.word {
  font-family: "Literata", Georgia, serif;
  font-weight: 700; font-size: var(--word-size);
  line-height: 0.92; letter-spacing: -0.018em;
  color: var(--ink); margin: 0; text-align: left; word-break: break-word;
}

.meta-row {
  display: flex; align-items: center; flex-wrap: wrap; gap: 14px 22px;
  margin-top: 22px;
}
.pos-it {
  font-family: "Literata", Georgia, serif; font-style: italic;
  font-size: clamp(19px, 1.9vw, 26px); color: var(--ink-soft);
}
.pron {
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: clamp(15px, 1.5vw, 20px); color: var(--muted); letter-spacing: 0.01em;
}

/* audio + tts chips (wrap Anki's {{Audio}} controls) */
.audio { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
.audio-btn, .mini {
  display: inline-flex; align-items: center; gap: 8px;
  border: 1px solid var(--line); background: var(--surface); color: var(--ink-soft);
  font: 600 13px/1 "Golos Text", sans-serif; letter-spacing: 0.01em;
  padding: 9px 14px; border-radius: 999px; cursor: pointer;
  transition: border-color .15s, color .15s, transform .12s;
}
.audio-btn:hover, .mini:hover { border-color: var(--accent); color: var(--accent); }
.audio-btn:active, .mini:active { transform: scale(0.96); }
.audio-btn.playing { border-color: var(--accent); color: var(--accent); }
/* native Anki <audio> replay glyphs sit inside .audio-container; keep them tidy */
.audio-container { display: flex; gap: 10px; align-items: center; }
.audio-container audio { max-height: 30px; }

.spk { display: inline-flex; gap: 2px; align-items: flex-end; height: 14px; }
.spk i { width: 2.5px; background: currentColor; border-radius: 2px; height: 5px; }
.audio-btn.playing .spk i { animation: bar 0.6s ease-in-out infinite; }
.audio-btn.playing .spk i:nth-child(2) { animation-delay: .12s; }
.audio-btn.playing .spk i:nth-child(3) { animation-delay: .24s; }
@keyframes bar { 0%,100% { height: 4px; } 50% { height: 13px; } }

/* ---- metadata definition rows (Back hero) ---- */
.meta-list { margin-top: clamp(24px, 3vw, 36px); display: flex; flex-direction: column; gap: 12px; }
.meta-line { display: flex; gap: 14px; align-items: baseline; }
.meta-line .k { flex: 0 0 auto; padding-top: 2px; }
.meta-line .v {
  font-family: "Literata", Georgia, serif;
  font-size: clamp(18px, 1.9vw, 24px); line-height: 1.4; color: var(--ink);
}
.meta-line.is-empty { display: none; }
.hl {
  background: linear-gradient(transparent 62%, var(--hl) 62%);
  padding: 0 2px; font-weight: 600; color: var(--ink);
}

/* ============================================================
   TRANSLATION (Back)
   ============================================================ */
.divider { height: 1px; background: var(--line); margin: clamp(30px,3.6vw,48px) 0; }

.translate-block { margin-bottom: clamp(8px,1vw,12px); }
.translate-block .k { margin-bottom: 14px; }
.tr-word, .translation {
  font-family: "Literata", Georgia, serif; font-weight: 700;
  font-size: clamp(40px, 4.6vw, 62px); line-height: 1.02;
  letter-spacing: -0.012em; color: var(--ink); text-align: left;
}

/* primary example (data.eu/eut) rendered into #top-llm-example */
.top-llm-example {
  margin-top: 24px; padding-left: 22px; border-left: 3px solid var(--accent);
}
.top-llm-example:empty { display: none; }
.top-llm-example-en {
  font-family: "Literata", Georgia, serif; font-style: italic;
  font-size: clamp(18px, 1.8vw, 23px); color: var(--ink); line-height: 1.45;
}
.top-llm-example-ru {
  margin-top: 8px; font-size: clamp(15px, 1.5vw, 18px); color: var(--muted); line-height: 1.45;
}

/* ============================================================
   DISCLOSURE primitives (shared)
   ============================================================ */
.disclose-row {
  appearance: none; border: none; background: none;
  display: inline-flex; align-items: center; gap: 9px; cursor: pointer;
  color: var(--ink-soft); font: 600 13px/1 "JetBrains Mono", monospace;
  letter-spacing: 0.1em; text-transform: uppercase; padding: 6px 0;
}
.disclose-row:hover { color: var(--accent); }
.chev { transition: transform .22s ease; color: var(--faint); }
details[open] > summary .chev,
.disclose-row[aria-expanded="true"] .chev { transform: rotate(90deg); color: var(--accent); }

/* mnemonic (image) */
.mnem { margin-top: 24px; }
.mnem > summary {
  list-style: none; cursor: pointer;
  display: inline-flex; align-items: center; gap: 9px;
  color: var(--ink-soft); font: 600 13px/1 "JetBrains Mono", monospace;
  letter-spacing: 0.1em; text-transform: uppercase; padding: 6px 0;
}
.mnem > summary::-webkit-details-marker { display: none; }
.mnem > summary:hover { color: var(--accent); }
.mnem-body {
  margin-top: 14px; padding: 18px; background: var(--bg-2);
  border-radius: 12px; border: 1px solid var(--line-soft);
  display: flex; flex-direction: column; align-items: center; gap: 12px;
}
.mnem-img {
  display: block; max-width: 100%; max-height: 360px; border-radius: 8px;
  border: 1px solid var(--line);
}
.mnem-links { font-size: 13px; color: var(--muted); display: flex; gap: 10px; align-items: center; }
.mnem-links a { color: var(--accent); text-decoration: none; border-bottom: 1px solid color-mix(in oklch, var(--accent) 40%, transparent); }
.mnem-links a:hover { border-bottom-color: var(--accent); }
.mnem-links .sep { color: var(--line); }
/* drag/drop placeholder appearance for the mnemonic image slot in preview */
.mnem-slot {
  width: 100%; min-height: 180px; border: 1.5px dashed var(--line);
  border-radius: 8px; display: flex; align-items: center; justify-content: center;
  background: repeating-linear-gradient(45deg, transparent 0 11px, color-mix(in oklch, var(--ink) 5%, transparent) 11px 12px);
  color: var(--faint); font: 600 11px/1.4 "JetBrains Mono", monospace;
  letter-spacing: 0.1em; text-transform: uppercase; text-align: center; padding: 20px;
}

/* ============================================================
   LOWER GRID (Back)
   ============================================================ */
.grid {
  display: grid; grid-template-columns: 1.55fr 1fr;
  gap: clamp(34px, 4vw, 60px); align-items: start;
}
.grid[data-llm="off"] { grid-template-columns: 1fr; }
.grid[data-llm="off"] .col-llm { display: none; }
@media (max-width: 900px) { .grid { grid-template-columns: 1fr; } }

.col-head {
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
  padding-bottom: 14px; margin-bottom: 20px; border-bottom: 2px solid var(--ink);
}
.col-llm .col-head { border-bottom-color: var(--line); }
.col-head .src {
  font-family: "JetBrains Mono", monospace; font-size: 10.5px;
  letter-spacing: 0.1em; text-transform: uppercase; color: var(--faint);
}

/* panel controls row (Раскрыть всё / Скрыть блюр) */
.panel-controls-row {
  display: flex; align-items: center; justify-content: space-between; gap: 14px;
  margin-bottom: 18px;
}
.panel-controls-row[hidden] { display: none; }
.panel-controls-label {
  font-family: "JetBrains Mono", monospace; font-size: 11px;
  letter-spacing: 0.12em; text-transform: uppercase; color: var(--muted);
}
.panel-controls-actions { display: inline-flex; gap: 8px; }
.news-mini-btn {
  appearance: none; border: 1px solid var(--line); background: var(--surface);
  color: var(--ink-soft); font: 600 11px/1 "JetBrains Mono", monospace;
  letter-spacing: 0.1em; text-transform: uppercase; padding: 8px 13px;
  border-radius: 999px; cursor: pointer; white-space: nowrap;
  transition: border-color .15s, color .15s;
}
.news-mini-btn:hover { border-color: var(--accent); color: var(--accent); }

/* ---------- Yomitan dictionary article ({{Value}}) ---------- */
.yomitan-card { /* wrapper card, kept transparent for clean look */ }
.yomitan-card.is-empty { display: none; }
.yomitan-definition { font-size: clamp(16px,1.6vw,18px); line-height: 1.55; color: var(--ink); }
.yomitan-definition > undefined,
.yomitan-glossary, .yomitan-glossary > undefined,
.yomitan-glossary > undefined > div { display: block; }

/* Grammar / Etymology preamble disclosures */
.yomitan-definition [data-content="preamble"] { margin-bottom: 8px; }
.yomitan-definition details[data-content^="details-entry-Grammar"],
.yomitan-definition details[data-content^="details-entry-Etymology"] {
  border-bottom: 1px solid var(--line-soft);
}
.yomitan-definition [data-content="preamble"] summary,
.yomitan-definition details[data-content^="details-entry-G"] summary,
.yomitan-definition details[data-content^="details-entry-E"] summary {
  list-style: none; cursor: pointer;
  display: flex; align-items: center; gap: 10px;
  font-family: "Golos Text", sans-serif; font-weight: 600;
  font-size: 15px; color: var(--ink); padding: 15px 0;
}
.yomitan-definition summary::-webkit-details-marker { display: none; }
.yomitan-definition [data-content="preamble"] summary::before {
  content: "›"; color: var(--faint); font-size: 18px; line-height: 1;
  transition: transform .2s ease; display: inline-block;
}
.yomitan-definition [data-content="preamble"] details[open] summary::before {
  transform: rotate(90deg); color: var(--accent);
}
.yomitan-definition [data-content$="-content"] {
  font-size: clamp(15px,1.5vw,16.5px); line-height: 1.6; color: var(--ink-soft);
  padding: 0 0 18px 28px;
}

/* glosses → numbered senses */
.yomitan-definition ol[data-content="glosses"] {
  list-style: none; margin: 24px 0 0; padding: 0;
}
.yomitan-definition ol[data-content="glosses"] > li {
  position: relative;
  padding: 18px 0 18px 46px; border-bottom: 1px solid var(--line-soft);
}
.yomitan-definition ol[data-content="glosses"] > li:last-child { border-bottom: none; }
.yomitan-definition .sense-num {
  position: absolute; left: 0; top: 16px;
  font-family: "Literata", Georgia, serif; font-weight: 700; font-size: 22px;
  color: var(--accent); line-height: 1.2;
}
.yomitan-definition ol[data-content="glosses"] > li > div { color: var(--ink); }

/* sense tags (ling / arithm / vdt / inf / golf …) */
.yomitan-definition [data-content="tags"] { display: inline; margin-right: 8px; }
.yomitan-definition [data-content="tag"] {
  display: inline-block; font-family: "JetBrains Mono", monospace;
  font-size: 10px; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase;
  color: var(--accent); background: color-mix(in oklch, var(--accent) 12%, transparent);
  padding: 2px 7px; border-radius: 4px; margin-right: 4px; vertical-align: 1px;
}

/* per-sense example disclosures */
.yomitan-definition details[data-content="details-entry-examples"] { margin-top: 10px; }
.yomitan-definition details[data-content="details-entry-examples"] > summary {
  list-style: none; cursor: pointer;
  display: inline-flex; align-items: center; gap: 8px;
  font-family: "JetBrains Mono", monospace; font-size: 11px;
  letter-spacing: 0.06em; text-transform: uppercase; color: var(--muted); padding: 4px 0;
}
.yomitan-definition details[data-content="details-entry-examples"] > summary::before {
  content: "›"; color: var(--faint); font-size: 15px; transition: transform .2s ease;
}
.yomitan-definition details[data-content="details-entry-examples"][open] > summary::before {
  transform: rotate(90deg); color: var(--accent);
}
.yomitan-definition [data-content="extra-info"] { margin: 8px 0; padding-left: 16px; position: relative; }
.yomitan-definition [data-content="extra-info"]::before {
  content: ""; position: absolute; left: 0; top: 11px;
  width: 5px; height: 5px; border-radius: 50%; background: var(--accent);
}
.yomitan-definition [data-content="example-sentence-a"] {
  font-family: "Literata", Georgia, serif; font-style: italic;
  font-size: clamp(14.5px,1.4vw,16px); line-height: 1.5; color: var(--ink-soft);
}
.yomitan-definition [data-content="bold-text"] { font-style: normal; font-weight: 700; color: var(--accent); }
.yomitan-definition [data-content="example-sentence-c"] {
  margin-top: 3px; font-size: 12px; color: var(--faint); line-height: 1.4;
}

/* glossary synonyms + backlink */
.yomitan-definition [data-content="synonyms"] { margin-top: 22px; }
.yomitan-definition [data-content="synonyms-label"] {
  font-family: "JetBrains Mono", monospace; font-size: 11px; font-weight: 600;
  letter-spacing: 0.14em; text-transform: uppercase; color: var(--faint); margin-bottom: 10px;
}
.yomitan-definition [data-content="synonyms-list"] {
  list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 8px;
}
.yomitan-definition [data-content="synonym-item"] {
  font-family: "Literata", serif; font-size: 15px; color: var(--ink-soft);
  border: 1px solid var(--line); border-radius: 999px; padding: 4px 12px;
}
.yomitan-definition [data-content="backlink"] {
  margin-top: 20px; font-family: "JetBrains Mono", monospace; font-size: 11px;
  letter-spacing: 0.06em; color: var(--faint);
}
.yomitan-definition [data-content="backlink"] a { color: var(--muted); text-decoration: none; }

/* КОНТЕКСТ card */
.context-card { margin-top: 22px; }
.context-card .k { display: block; margin-bottom: 10px; }
.yomitan-example {
  font-family: "Literata", serif; font-style: italic;
  font-size: clamp(16px,1.6vw,18px); line-height: 1.5; color: var(--ink-soft);
  padding-left: 18px; border-left: 3px solid var(--line);
}

/* ---------- LLM examples + synonyms ---------- */
.llm-card { display: flex; flex-direction: column; gap: 4px; }
.llm-items-list { list-style: none; margin: 0; padding: 0; }
.news-class-item { padding: 16px 0; border-bottom: 1px solid var(--line-soft); }
.news-class-item:first-child { padding-top: 0; }
.llm-item-en {
  font-family: "Literata", serif; font-style: italic;
  font-size: clamp(16px,1.6vw,18.5px); line-height: 1.45; color: var(--ink);
}
.llm-item-ru { margin-top: 6px; font-size: 15px; color: var(--muted); line-height: 1.45; }
.llm-item-comment {
  margin-top: 9px; font-family: "JetBrains Mono", monospace; font-size: 10px;
  letter-spacing: 0.08em; text-transform: uppercase; color: var(--faint);
}
.news-syn { margin-top: 26px; }
.llm-title, .news-syn-h {
  font-family: "JetBrains Mono", monospace; font-size: 11.5px; font-weight: 600;
  letter-spacing: 0.18em; text-transform: uppercase; color: var(--faint); margin-bottom: 14px;
}
.llm-syn-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; }
.news-syn-item {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px;
  padding: 11px 0; border-bottom: 1px solid var(--line-soft);
}
.news-syn-item:last-child { border-bottom: none; }
.llm-syn-word { font-family: "Literata", serif; font-weight: 700; font-size: clamp(17px,1.7vw,20px); color: var(--ink); }
.llm-muted { font-family: "JetBrains Mono", monospace; font-style: normal; font-size: 11px; color: var(--faint); }
.llm-empty, .llm-error { font-style: italic; color: var(--muted); padding: 10px 0; }
.llm-error { color: var(--accent); white-space: pre-wrap; }

/* blur reveal */
.blur-text {
  display: inline-block; filter: blur(0.32em); -webkit-filter: blur(0.32em);
  transition: filter .18s ease, background-color .18s ease;
  cursor: pointer; user-select: none; padding: 0 0.18em; border-radius: 3px;
  background: color-mix(in oklch, var(--ink) 8%, transparent);
}
.blur-text.is-revealed, body.llm-unblur-all .blur-text { filter: none; -webkit-filter: none; background: transparent; }

/* ============================================================
   FRONT — quiz, voice, dictation, mnemonic ad
   ============================================================ */
.front-context {
  margin-top: clamp(26px,3.2vw,40px);
  font-family: "Literata", serif; font-size: clamp(21px, 2.2vw, 30px);
  line-height: 1.4; color: var(--ink);
}
.front-context .k { display: block; margin-bottom: 10px; }

/* voice input slot */
.voice-input {
  margin-top: 22px; padding: 14px 18px; border: 1.5px dashed var(--line);
  border-radius: 12px; background: var(--bg-2); min-height: 54px;
  display: flex; align-items: center; gap: 10px;
  font-family: "JetBrains Mono", monospace; font-size: 14px; color: var(--faint);
}
.voice-input::before { content: "🎤"; filter: grayscale(1); opacity: .6; }
.voice-final { color: var(--ink); font-weight: 600; font-family: "Golos Text", sans-serif; }
.voice-interim { color: var(--accent); font-style: italic; font-family: "Golos Text", sans-serif; }

/* quiz */
.quiz { margin-top: clamp(30px,3.6vw,46px); }
.quiz > summary {
  list-style: none; cursor: pointer;
  display: flex; align-items: baseline; justify-content: space-between; gap: 14px;
  padding-bottom: 14px; border-bottom: 2px solid var(--ink);
}
.quiz > summary::-webkit-details-marker { display: none; }
.quiz-h { font-family: "JetBrains Mono", monospace; font-size: 12px; font-weight: 600; letter-spacing: 0.16em; text-transform: uppercase; color: var(--ink); }
.quiz-sub { font-size: 13px; color: var(--muted); }
.news-timer { font-family: "JetBrains Mono", monospace; color: var(--accent); font-weight: 600; }
.news-choices { display: flex; flex-direction: column; gap: 10px; margin-top: 20px; }
.news-choices--locked { pointer-events: none; }
.news-choice {
  appearance: none; text-align: left; cursor: pointer;
  font-family: "Literata", serif; font-size: clamp(18px,1.8vw,22px); color: var(--ink);
  padding: 16px 20px; background: var(--surface);
  border: 1px solid var(--line); border-radius: 12px;
  transition: border-color .15s, background .15s, color .15s, transform .1s;
}
.news-choice:hover { border-color: var(--accent); transform: translateX(3px); }
.news-choice--ok {
  border-color: var(--accent); color: var(--accent);
  background: color-mix(in oklch, var(--accent) 10%, transparent); font-weight: 600;
}
.news-choice--ok::after { content: " ✓"; }
.news-choice--bad { border-color: var(--line); color: var(--muted); text-decoration: line-through; }
.news-choice--dim { opacity: 0.4; }

/* dictation helper */
.dictation { margin-top: 26px; display: flex; align-items: center; gap: 12px; }
.dictation .k { margin-right: 4px; }

/* mnemonic on front (reuses .mnem look) */
.mnem-front-big {
  font-family: "Literata", serif; font-weight: 700; font-style: italic;
  font-size: clamp(28px,3vw,40px); color: var(--ink-soft);
}

/* ============================================================
   Copy-selection floating button
   ============================================================ */
.copy-selection-btn {
  position: fixed; z-index: 9999; display: inline-flex; align-items: center; justify-content: center;
  width: 36px; height: 36px; border-radius: 10px;
  border: 1px solid var(--line); background: var(--surface); color: var(--ink-soft);
  cursor: pointer; box-shadow: 0 6px 18px oklch(0.3 0.02 60 / 0.16);
  font-size: 15px; opacity: 0; transform: translate3d(0,8px,0) scale(.92); pointer-events: none;
  transition: opacity .18s ease, transform .18s ease;
}
.copy-selection-btn.is-visible { opacity: 1; transform: translateY(0) scale(1); pointer-events: auto; }
.copy-selection-btn.is-copied { background: var(--accent); color: var(--bg); border-color: var(--accent); }

button:focus-visible, summary:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }


/* === fix-2026-06-04: full-viewport bg + clickable result-icon === */
html, body { min-height: 100vh; }
.card { min-height: 100vh; box-sizing: border-box; }
.result-icon { cursor: pointer; }
.result-icon:hover { border-color: var(--accent); color: var(--accent); }


/* === flib_media: saved film clips (WebM + VTT) and YouTube links ===
   Back only, inside .sheet right under the hero, so it shows on the first
   screen without scrolling (the sheet supplies the theme background and the
   column inset). With both a clip and links it splits like the lower .grid
   (clip | links) and stacks under 900px. The video is capped by its column
   width and by the viewport height (100vh minus a typical hero ~405px and the
   clip frame ~50px) so the whole block fits even a 600px-high reviewer. */
.flib-media {
  margin: 0; color: var(--ink);
  font-family: "Golos Text", ui-sans-serif, system-ui, sans-serif;
}
.flib-media:empty { display: none; }
.flib-media:has(.flib-clip):has(.flib-yt) {
  display: grid; grid-template-columns: minmax(0, 1.55fr) minmax(0, 1fr);
  column-gap: clamp(34px, 4vw, 60px); align-items: start;
}
.flib-media:has(.flib-clip):has(.flib-yt) .flib-clip { grid-column: 1; }
.flib-media:has(.flib-clip):has(.flib-yt) .flib-yt { grid-column: 2; grid-row: 1; margin-top: 0; }
@media (max-width: 900px) {
  .flib-media:has(.flib-clip):has(.flib-yt) { display: block; }
  .flib-media:has(.flib-clip):has(.flib-yt) .flib-yt { margin-top: 16px; }
}
.flib-media .flib-clip {
  margin: 0; padding: 12px;
  background: var(--surface); border: 1px solid var(--line); border-radius: 12px;
}
.flib-media .flib-clip + .flib-clip, .flib-media .flib-clip + .flib-yt { margin-top: 16px; }
.flib-media video {
  max-width: 100%; max-height: clamp(140px, calc(100vh - 460px), 420px); width: auto; height: auto;
  display: block; margin: 0 auto; border-radius: 8px; background: #000;
}
.flib-media video::cue { background: rgba(0, 0, 0, 0.72); color: #fff; }
.flib-media video::cue(.hl) { color: #ffd400; font-weight: bold; }
.flib-media .flib-clip-src {
  margin-top: 8px; font-size: 13px; color: var(--muted);
}
.flib-media .flib-clip-src a { color: var(--ink-soft); text-decoration: none; border-bottom: 1px solid var(--line); }
.flib-media .flib-clip-src a:hover { color: var(--accent); border-bottom-color: var(--accent); }
.flib-media .flib-yt {
  list-style: none; margin: 0; padding: 0;
  border-top: 1px solid var(--line-soft);
}
.flib-media .flib-yt li { padding: 8px 0; border-bottom: 1px solid var(--line-soft); font-size: 15px; line-height: 1.45; }
.flib-media .flib-yt a { color: var(--ink-soft); text-decoration: none; }
.flib-media .flib-yt a:hover { color: var(--accent); }
.flib-media .flib-yt b { color: var(--accent); font-weight: 600; }
